using System.Text.Json;
using Impersonate.Domain.Ai;
namespace Impersonate.Application.Ai;

internal sealed class DeterministicTaskProfiler:ITaskProfiler
{
 private static readonly string[] HighSignals=["architecture","migration","security","concurrency","redesign","integration"];
 public TaskProfile Profile(AgentRole role,string description)=>Profile(new(Guid.Empty,null,role,description));
 public TaskProfile Profile(ModelSelectionRequest request)
 {
  var text=string.Join(' ',new[]{request.TaskTitle,request.Description,request.FeatureRequest,request.ChangeType,string.Join(' ',request.AcceptanceCriteria??[]),string.Join(' ',request.AffectedAreas??[]),request.ReviewerFeedback}.Where(x=>!string.IsNullOrWhiteSpace(x)));var security=text.Contains("security",StringComparison.OrdinalIgnoreCase)||text.Contains("credential",StringComparison.OrdinalIgnoreCase)||text.Contains("auth",StringComparison.OrdinalIgnoreCase);var concurrency=text.Contains("concurr",StringComparison.OrdinalIgnoreCase)||text.Contains("claim",StringComparison.OrdinalIgnoreCase)||text.Contains("transaction",StringComparison.OrdinalIgnoreCase);var database=text.Contains("migration",StringComparison.OrdinalIgnoreCase)||text.Contains("database",StringComparison.OrdinalIgnoreCase)||text.Contains("persistence",StringComparison.OrdinalIgnoreCase);var architecture=HighSignals.Any(x=>text.Contains(x,StringComparison.OrdinalIgnoreCase));var high=text.Length>1200||security||concurrency||request.Risk.Equals("High",StringComparison.OrdinalIgnoreCase)||request.ConflictRisk.Equals("High",StringComparison.OrdinalIgnoreCase);var simple=text.Length<300&&!high;var complexity=high?TaskComplexity.High:simple?TaskComplexity.Simple:TaskComplexity.Moderate;var type=TaskType(request.ChangeType,text);var reasons=new List<string>{$"Profiled as {type} for the {request.Role} role.",high?"Repository/task evidence indicates high risk, architecture, security, concurrency, or context demand.":simple?"The bounded task is small and low-signal.":"The task has moderate scope and evidence."};return new(request.Role,complexity,high?RiskLevel.High:RiskLevel.Moderate,request.Role==AgentRole.Coder,true,request.Role is AgentRole.Planner or AgentRole.Reviewer,request.Role==AgentRole.Coder,Math.Max(2000,text.Length*3),high?Sensitivity.Low:Sensitivity.Balanced,simple?Sensitivity.High:Sensitivity.Balanced,reasons,type,request.RepositoryLanguages??[],request.RepositoryFrameworks??[],request.AffectedAreas??[],request.ChangeType,request.ConflictRisk,database,security,concurrency,architecture,request.AttemptNumber,request.PriorFailures,request.RevisionCount,request.ReviewerFeedback,Math.Max(1000,text.Length*2));
 }
 private static EngineeringTaskType TaskType(string changeType,string text){var value=changeType+" "+text;foreach(var candidate in Enum.GetValues<EngineeringTaskType>().Where(x=>x!=EngineeringTaskType.Unknown))if(value.Contains(candidate.ToString(),StringComparison.OrdinalIgnoreCase))return candidate;if(value.Contains("migration",StringComparison.OrdinalIgnoreCase))return EngineeringTaskType.DatabaseMigration;if(value.Contains("endpoint",StringComparison.OrdinalIgnoreCase)||value.Contains(" api ",StringComparison.OrdinalIgnoreCase))return EngineeringTaskType.ApiEndpoint;if(value.Contains("frontend",StringComparison.OrdinalIgnoreCase)||value.Contains(" ui ",StringComparison.OrdinalIgnoreCase))return EngineeringTaskType.FrontendUi;if(value.Contains("test",StringComparison.OrdinalIgnoreCase))return EngineeringTaskType.Testing;return EngineeringTaskType.Unknown;}
}

internal sealed class VersionedModelCapabilityCatalog:IModelCapabilityCatalog
{
 private const string Version="catalog-2026-07-v1";private static readonly HashSet<AgentRole> All=[AgentRole.Planner,AgentRole.Coder,AgentRole.Reviewer];
 public ModelCapabilityProfile Resolve(ProviderType provider,string modelId)
 {
  var id=modelId.ToLowerInvariant();if(id.Contains("gpt-4.1")||id.Contains("claude-3-7")||id.Contains("claude-sonnet-4"))return new(modelId,All,4,4,4,4,4,4,3,3,new HashSet<string>(StringComparer.OrdinalIgnoreCase){"C#","TypeScript","JavaScript","Python"},new HashSet<string>(StringComparer.OrdinalIgnoreCase){".NET","React"},Version);if(id.Contains("mini")||id.Contains("haiku")||id.Contains("flash"))return new(modelId,All,3,3,3,4,4,3,1,1,new HashSet<string>(),new HashSet<string>(),Version);return new(modelId,All,1,1,1,1,1,2,2,2,new HashSet<string>(),new HashSet<string>(),Version,true);
 }
}

internal sealed class DeterministicModelRouter(IAiRoutingRepository repository,ITaskProfiler profiler,IModelCapabilityCatalog catalog):IModelRouter
{
 public async Task<ModelSelectionResult> SelectAsync(ModelSelectionRequest request,CancellationToken ct)
 {
  var profile=profiler.Profile(request);var policy=await repository.GetPolicyAsync(request.ProjectId,ct)??ProjectAiRoutingPolicy.Create(request.ProjectId);var connections=(await repository.GetConnectionsAsync(ct)).Where(x=>x.Status==ProviderConnectionStatus.Connected).ToDictionary(x=>x.Id);var allowed=JsonSerializer.Deserialize<ProviderType[]>(policy.AllowedProvidersJson)??[];var blocked=JsonSerializer.Deserialize<ProviderType[]>(policy.BlockedProvidersJson)??[];
  var candidates=(await repository.GetModelsAsync(null,ct)).Where(x=>x.IsAvailable&&x.LifecycleStatus!=ModelLifecycleStatus.Deprecated&&connections.ContainsKey(x.ProviderConnectionId)&&(policy.AllowPreviewModels||x.LifecycleStatus!=ModelLifecycleStatus.Preview)&&!(request.ExcludedModels?.Contains(x.Id)??false)&&(allowed.Length==0||allowed.Contains(x.ProviderType))&&!blocked.Contains(x.ProviderType)).Select(x=>(Model:x,Discovery:Parse(x.CapabilitiesJson),Catalog:catalog.Resolve(x.ProviderType,x.ProviderModelId))).Where(x=>SupportsRequest(request.Role,profile,x.Discovery,x.Catalog,x.Model)).Select(x=>Score(x.Model,x.Discovery,x.Catalog,profile,policy,request)).OrderByDescending(x=>x.Score).ThenBy(x=>x.ProviderType).ThenBy(x=>x.ProviderModelId,StringComparer.Ordinal).ToList();
  var overrideId=request.ManualModelOverrideId??policy.FixedModelOverrideId;if(candidates.Count==0)return overrideId is not null?new(false,profile,null,[],"invalid_override","The selected model is unavailable or does not meet this role's requirements."):new(false,profile,null,[],"no_eligible_model",connections.Count==0?"No connected AI providers are available.":$"No discovered model satisfies the {request.Role} requirements and project policy.");var best=candidates[0];var ranked=candidates.Skip(1).Select(x=>x with{RankedLowerReason=$"Ranked {best.Score-x.Score} points lower than {best.ProviderModelId} under the same role profile and project policy."}).ToList();if(overrideId is not null){var chosen=candidates.FirstOrDefault(x=>x.DiscoveredModelId==overrideId);if(chosen is null)return new(false,profile,null,candidates,"invalid_override","The selected model is unavailable or does not meet this role's requirements.");chosen=chosen with{Source=ModelSelectionSource.ManualOverride,Explanation="Selected by an explicit task override after role-specific compatibility validation."};return new(true,profile,chosen,candidates.Where(x=>x.DiscoveredModelId!=overrideId).ToList(),null,null);}return new(true,profile,best,ranked,null,null);
 }
 private static bool SupportsRequest(AgentRole role,TaskProfile profile,ModelCapability discovered,ModelCapabilityProfile model,DiscoveredModel record)=>model.SupportedRoles.Contains(role)&&discovered.HasFlag(ModelCapability.TextGeneration)&&(!profile.RequiresStructuredOutput||discovered.HasFlag(ModelCapability.StructuredOutput))&&(!profile.RequiresTools||discovered.HasFlag(ModelCapability.ToolUse))&&record.ContextWindowSize.GetValueOrDefault(int.MaxValue)>=profile.EstimatedContextSize;
 private static SelectedModel Score(DiscoveredModel model,ModelCapability discovered,ModelCapabilityProfile metadata,TaskProfile profile,ProjectAiRoutingPolicy policy,ModelSelectionRequest request){var parts=new List<ScoreComponent>{new("Hard compatibility",20,$"Discovery metadata satisfies the {profile.Role} hard requirements.")};var role=profile.Role switch{AgentRole.Coder=>metadata.CodingStrength,AgentRole.Reviewer=>metadata.ReviewStrength,_=>metadata.ReasoningStrength};parts.Add(new("Role fit",role*8,$"Versioned catalog role-fit tier is {role}/4 for {profile.Role}."));var taskFit=(profile.Languages??[]).Count(x=>metadata.LanguageAffinities.Contains(x))*4+(profile.Frameworks??[]).Count(x=>metadata.FrameworkAffinities.Contains(x))*4;parts.Add(new("Task and stack fit",taskFit,taskFit>0?"Catalog affinities overlap the detected repository stack.":"No reviewed language/framework affinity bonus was applied."));parts.Add(new("Complexity and risk",profile.Complexity==TaskComplexity.High?metadata.ReasoningStrength*4:metadata.ReasoningStrength*2,$"Reasoning tier was weighted for {profile.Complexity} complexity and {profile.Risk} risk."));parts.Add(new("Context fit",metadata.ContextTier*3,$"Context tier {metadata.ContextTier} was compared with the estimated {profile.EstimatedContextSize} token context."));parts.Add(new("Tool compatibility",profile.RequiresTools?metadata.ToolUseStrength*3:0,profile.RequiresTools?"Coder execution requires the provider-neutral repository tool protocol.":"This role does not require modifying repository tools."));parts.Add(new("Structured output",profile.RequiresStructuredOutput?metadata.StructuredOutputStrength*3:0,profile.RequiresStructuredOutput?"The role requires validated structured output.":"Structured output is not a hard requirement for this request."));parts.Add(new("Cost policy",policy.CostPreference==RoutingPreference.Economy?(5-metadata.CostTier)*3:2,$"Relative cost tier {metadata.CostTier} was evaluated under {policy.CostPreference} policy."));parts.Add(new("Latency policy",policy.LatencyPreference==RoutingPreference.Economy?(5-metadata.LatencyTier)*2:1,$"Relative latency tier {metadata.LatencyTier} was evaluated under {policy.LatencyPreference} policy."));if(policy.PreferredProvider==model.ProviderType)parts.Add(new("Preferred provider",10,"The model belongs to the project's preferred provider."));ScoreComponent? diversity=null;if(profile.Role==AgentRole.Reviewer&&policy.PreferReviewerDiversity&&request.CoderModelId is not null){var different=model.Id!=request.CoderModelId;diversity=new("Reviewer diversity",different?policy.ReviewerDiversityWeight:0,different?"A different Reviewer model was selected to reduce correlated implementation and review blind spots.":"The same model was selected because no alternative exceeded its role-fit score after applying the configured diversity preference.");parts.Add(diversity);}parts.Add(new("Historical outcomes",0,"Historical performance was not used because insufficient samples exist (minimum 10)."));var total=parts.Sum(x=>x.Score);var explanation=string.Join(" ",parts.Where(x=>x.Score>0).OrderByDescending(x=>x.Score).Take(4).Select(x=>x.Reason));if(diversity is not null)explanation+=" "+diversity.Reason;return new(model.ProviderConnectionId,model.Id,model.ProviderType,model.ProviderModelId,ModelSelectionSource.AutomaticRouting,total,explanation,parts,metadata.MetadataVersion);
 }
 private static ModelCapability Parse(string json){try{return(ModelCapability)(JsonSerializer.Deserialize<int>(json));}catch{return ModelCapability.None;}}
}
